import{_ as e,o as l,c as o,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-08-31","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-08-31","date":"2021-08-31T00:00:00.000Z","updated":"2021-09-03T00:00:00.000Z","tags":["Ceph","分布式存储","LVM","TopoLVM","Rook"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-08-31.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-08-31.md","lastUpdated":1780460162000}'),i={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-08-31.md"};function r(s,a,n,h,p,d){return l(),o("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-本地存储解决方案讨论" tabindex="-1">会议主题：本地存储解决方案讨论 <a class="header-anchor" href="#会议主题-本地存储解决方案讨论" aria-label="Permalink to &quot;会议主题：本地存储解决方案讨论&quot;">​</a></h4><h4 id="参会人员-sage、其他内部ocs团队成员" tabindex="-1">参会人员：Sage、其他内部OCS团队成员 <a class="header-anchor" href="#参会人员-sage、其他内部ocs团队成员" aria-label="Permalink to &quot;参会人员：Sage、其他内部OCS团队成员&quot;">​</a></h4><h4 id="会议时间-最近几周的定期会议" tabindex="-1">会议时间：最近几周的定期会议 <a class="header-anchor" href="#会议时间-最近几周的定期会议" aria-label="Permalink to &quot;会议时间：最近几周的定期会议&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>本地存储需求和要求</strong>：</p><ul><li>讨论了本地存储的需求，包括动态和静态资源配置。</li><li>提供了文档链接，记录了过去几周的会议讨论内容。</li></ul></li><li><p><strong>动态资源配置方案</strong>：</p><ul><li>初步倾向于使用LVM进行动态资源配置，因为它提供了已知的有益功能，避免了使用分区。</li><li>探讨了LSO与TopoLVM的结合使用，以及设备发现和资源分配。</li></ul></li><li><p><strong>社区和项目归属问题</strong>：</p><ul><li>讨论了将项目捐赠给CNCF的可能性。</li><li>探讨将项目纳入Rook项目下，以简化流程。</li></ul></li><li><p><strong>技术细节讨论</strong>：</p><ul><li>讨论了静态和动态资源配置的优缺点。</li><li>探讨在TopoLVM中实现对原始设备的支持。</li></ul></li><li><p><strong>未来发展和兼容性</strong>：</p><ul><li>讨论了未来可能需要支持的设备类型，如Crimson和ZNS。</li><li>探讨如何在保持灵活性的同时，确保系统的长期兼容性和扩展性。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>继续与TopoLVM团队沟通，探讨加入Rook项目的可能性，以及如何在TopoLVM中实现对原始设备的支持。</li><li>安排与TopoLVM团队的进一步会议，讨论技术实现和项目归属问题。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>与TopoLVM团队进行深入的技术和项目归属讨论。</li><li>关注LSO和TopoLVM的最新进展，确保项目的动态资源配置功能满足未来的需求。</li><li>探索备选方案，以应对TopoLVM团队可能的不同意见或技术挑战。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在讨论了所有议题后结束，没有其他紧急议题需要处理。</li></ul><p>本次会议记录了关于本地存储解决方案的关键讨论点，包括技术实现、社区合作和未来发展方向，为后续的行动计划提供了明确的方向。</p>',13)])])}const _=e(i,[["render",r]]);export{c as __pageData,_ as default};
